import{_ as o,C as s,c as n,o as i,a3 as t,G as r}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Take an order","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/selling/take-an-order.md","filePath":"master/sales/point-of-sale/selling/take-an-order.md","lastUpdated":1792041590000}'),l={name:"master/sales/point-of-sale/selling/take-an-order.md"};function d(h,e,c,p,u,g){const a=s("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="take-an-order" tabindex="-1">Take an order <a class="header-anchor" href="#take-an-order" aria-label="Permalink to &quot;Take an order&quot;">​</a></h1><p>An order is one sale at the till. You add products, check the total and take payment. This page follows a retail sale from the first product to the payment screen, using the TechNest Electronics shop.</p><blockquote><p><strong>In simple words:</strong> Tap the products, fix the quantities, then click Payment.</p></blockquote><p>Make sure the register is open first. See <a href="./../sessions/open-register.html">Open the register</a>.</p><h2 id="start-the-order" tabindex="-1">Start the order <a class="header-anchor" href="#start-the-order" aria-label="Permalink to &quot;Start the order&quot;">​</a></h2><p>When the register opens, an empty order is ready. The order panel says &quot;Scan or tap a product to start&quot;. The order gets a tracking number, such as <strong>401</strong>.</p><p>To start another order at any time, click the <strong>+</strong> tab at the top right. The old order stays open under its own tab.</p><h2 id="add-products" tabindex="-1">Add products <a class="header-anchor" href="#add-products" aria-label="Permalink to &quot;Add products&quot;">​</a></h2><ol><li>Click a category tile, such as <strong>Accessories</strong>, or type in <strong>Search products</strong>.</li><li>Click the product tile. One unit goes to the order.</li><li>Click the tile again to add one more unit.</li></ol>',9)),r(a,{src:"/images1/pos/take_order_add_products.png",alt:"Retail terminal with Glide Wireless Mouse quantity 2 and BudsAir Wireless Earbuds on the order panel"}),e[1]||(e[1]=t('<p><strong>Example:</strong> Sofia Rossi wants two Glide Wireless Mouse and one BudsAir Wireless Earbuds. Click <strong>Glide Wireless Mouse</strong> twice and <strong>BudsAir Wireless Earbuds</strong> once. The panel shows:</p><ul><li>Glide Wireless Mouse, 2 x 1,299, line total 2,598</li><li>BudsAir Wireless Earbuds, 1 x 3,999, line total 3,999</li><li><strong>Total:</strong> 6,597</li></ul><p>If a product has variants, a window asks you to pick the attributes. If it needs a lot or serial number, a window asks for the number.</p><h2 id="change-a-quantity" tabindex="-1">Change a quantity <a class="header-anchor" href="#change-a-quantity" aria-label="Permalink to &quot;Change a quantity&quot;">​</a></h2><ol><li>Click the line in the order panel. It turns blue.</li><li>Make sure the number pad is in <strong>Qty</strong> mode.</li><li>Type the new quantity, for example 3.</li></ol>',5)),r(a,{src:"/images1/pos/take_order_change_qty.png",alt:"Selected Glide Wireless Mouse line with the number pad in Qty mode"}),e[2]||(e[2]=t('<p>Use <strong>+/-</strong> to change the sign and the backspace key to delete a digit.</p><h2 id="remove-a-line" tabindex="-1">Remove a line <a class="header-anchor" href="#remove-a-line" aria-label="Permalink to &quot;Remove a line&quot;">​</a></h2><p>Click the <strong>X</strong> at the right end of the line. The line disappears and the total updates.</p><h2 id="discount-or-price-on-a-line" tabindex="-1">Discount or price on a line <a class="header-anchor" href="#discount-or-price-on-a-line" aria-label="Permalink to &quot;Discount or price on a line&quot;">​</a></h2><p>Select the line, then click <strong>%</strong> or <strong>Price</strong> on the number pad.</p><ul><li><strong>%:</strong> Type the discount percentage. The line then shows &quot;5% discount&quot;, for example.</li><li><strong>Price:</strong> Type a new unit price for this order only.</li></ul><p>These modes work only when your register allows them. Line discounts are a setting of the register. See <a href="./../get-started/pos-settings.html">POS settings</a> and <a href="./../get-started/set-up-a-register.html">Set up a register</a>.</p><h2 id="add-a-customer-or-a-note" tabindex="-1">Add a customer or a note <a class="header-anchor" href="#add-a-customer-or-a-note" aria-label="Permalink to &quot;Add a customer or a note&quot;">​</a></h2><p>Click <strong>Customer</strong> to attach a person to the sale. Click <strong>Note</strong> to write a message on a line. See <a href="./order-notes-and-customers.html">Notes and customers</a>.</p><h2 id="cancel-the-order" tabindex="-1">Cancel the order <a class="header-anchor" href="#cancel-the-order" aria-label="Permalink to &quot;Cancel the order&quot;">​</a></h2><p>Click <strong>Actions</strong>, then <strong>Cancel order</strong>, then <strong>Confirm</strong>. The lines are lost and this cannot be undone.</p>',11)),r(a,{src:"/images1/pos/take_order_actions_retail.png",alt:"Actions window on a retail order showing only the Cancel order button"}),e[3]||(e[3]=t('<h2 id="continue-to-payment" tabindex="-1">Continue to payment <a class="header-anchor" href="#continue-to-payment" aria-label="Permalink to &quot;Continue to payment&quot;">​</a></h2><p>When the order is right, click <strong>Payment</strong>. See <a href="./pay-and-receipt.html">Pay and receipt</a>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li>A new order has the status <strong>New</strong> until you validate the payment.</li><li>After payment the status is <strong>Paid</strong>.</li><li>Cancelled orders show <strong>Cancelled</strong>.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Keep two or three orders open on separate tabs when customers are waiting. Switch between them with the tabs.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Prices follow the register&#39;s price list and tax setting. See <a href="./../products-pricing/pricing-and-taxes.html">Pricing and taxes</a>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./terminal-overview.html">Terminal tour</a></li><li><a href="./pay-and-receipt.html">Pay and receipt</a></li><li><a href="./refunds.html">Refunds</a></li></ul>',8))])}const k=o(l,[["render",d]]);export{_ as __pageData,k as default};
